      body: "Pretraining a 70B dense model costs tens of millions of dollars, limiting who can afford to train."
    },
    {
      icon: MdMemory,
      title: "KV Cache Bottleneck",
      body: "Standard MHA caches full key-value pairs per head per token, making long-context inference memory-bound."
    },
  ];

  challenges.forEach((c, i) => {
    const x = 0.5 + i * 3.1;
    // Card background
    slide2.addShape(pres.shapes.RECTANGLE, {
      x, y: 2.45, w: 2.9, h: 2.75,
      fill: { color: C.white }, shadow: mkShadow(0.12)
    });
    // Icon circle
    const iconImg = await iconPng(c.icon, "#" + C.accent, 256);
    slide2.addImage({
      data: iconImg, x: x + 0.15, y: 2.6, w: 0.5, h: 0.5
    });
    // Title
    slide2.addText(c.title, {
      x: x + 0.75, y: 2.62, w: 2.0, h: 0.45,
      fontSize: 14, fontFace: "Arial", color: C.text, bold: true, valign: "middle", margin: 0
    });
    // Body
    slide2.addText(c.body, {
      x: x + 0.15, y: 3.2, w: 2.6, h: 1.8,
      fontSize: 12, fontFace: "Arial", color: C.text, valign: "top"
    });
  });

  // Bottom takeaway
  slide2.addShape(pres.shapes.RECTANGLE, { x: 0.5, y: 5.25, w: 9, h: 0.02, fill: { color: C.accent } });
  slide2.addText("→  MoE + efficient attention are needed to break the cost-performance trade-off", {
    x: 0.5, y: 5.3, w: 9, h: 0.28,
    fontSize: 12, fontFace: "Arial", color: C.primary, italic: true
  });

  // ═══════════════════════════════════════════════════════════════════════════════
  // SLIDE 3 — Architecture Overview
  // ═══════════════════════════════════════════════════════════════════════════════
  const slide3 = pres.addSlide();
  slide3.background = { color: C.light };

  slide3.addShape(pres.shapes.RECTANGLE, { x: 0, y: 0, w: 10, h: 0.85, fill: { color: C.darkBg } });
  slide3.addText("DeepSeek-V2 Architecture: MLA + DeepSeekMoE in a Transformer Block", {
    x: 0.5, y: 0.15, w: 9, h: 0.55,
    fontSize: 17, fontFace: "Arial", color: C.white, bold: true, margin: 0
  });

  // Architecture image
  const fig1Data = await sharp("/app/benchmark/assets/figure_1.jpg")
    .resize({ width: 900 })
    .jpeg({ quality: 88 })
    .toBuffer();
  slide3.addImage({
    data: "image/jpeg;base64," + fig1Data.toString("base64"),
    x: 0.5, y: 1.0, w: 9, h: 3.4
  });

  // Caption
  slide3.addText("Figure 1: DeepSeek-V2 block with Multi-Head Latent Attention (MLA) and DeepSeekMoE replacing standard attention and dense FFN.", {
    x: 0.5, y: 4.5, w: 9, h: 0.3,
    fontSize: 10, fontFace: "Arial", color: C.muted, italic: true
  });

  // Key callouts below
  slide3.addShape(pres.shapes.RECTANGLE, { x: 0.5, y: 4.9, w: 4.3, h: 0.6, fill: { color: C.cardLight }, shadow: mkShadow(0.1) });
  slide3.addShape(pres.shapes.RECTANGLE, { x: 0.5, y: 4.9, w: 0.07, h: 0.6, fill: { color: C.accent } });
  slide3.addText("MLA replaces standard MHA: low-rank KV compression → 93.3% cache reduction", {
    x: 0.7, y: 4.95, w: 4.0, h: 0.5, fontSize: 11, fontFace: "Arial", color: C.text, valign: "middle"
  });

  slide3.addShape(pres.shapes.RECTANGLE, { x: 5.2, y: 4.9, w: 4.3, h: 0.6, fill: { color: C.cardLight }, shadow: mkShadow(0.1) });
  slide3.addShape(pres.shapes.RECTANGLE, { x: 5.2, y: 4.9, w: 0.07, h: 0.6, fill: { color: C.primary } });
  slide3.addText("DeepSeekMoE replaces dense FFN: shared + routed experts, top-K routing", {
    x: 5.4, y: 4.95, w: 4.0, h: 0.5, fontSize: 11, fontFace: "Arial", color: C.text, valign: "middle"
  });

  // ═══════════════════════════════════════════════════════════════════════════════
  // SLIDE 4 — MLA Mechanism
  // ═══════════════════════════════════════════════════════════════════════════════
  const slide4 = pres.addSlide();
  slide4.background = { color: C.light };

  slide4.addShape(pres.shapes.RECTANGLE, { x: 0, y: 0, w: 10, h: 0.85, fill: { color: C.darkBg } });
  slide4.addText("Multi-Head Latent Attention Compresses KV Cache by 93.3%", {
    x: 0.5, y: 0.15, w: 9, h: 0.55,
    fontSize: 18, fontFace: "Arial", color: C.white, bold: true, margin: 0
  });

  // MLA comparison image
  const fig2Data = await sharp("/app/benchmark/assets/figure_2.jpg")
    .resize({ width: 900 })
    .jpeg({ quality: 88 })
    .toBuffer();
  slide4.addImage({
    data: "image/jpeg;base64," + fig2Data.toString("base64"),
    x: 0.5, y: 1.0, w: 6.2, h: 3.6
  });

  // Right-side explanation cards
  const mlaPoints = [
    { title: "MHA (Baseline)", body: "Full K,V per head per token. High memory, best quality." },
    { title: "GQA / MQA", body: "Shared K,V across heads. Less cache but degraded quality." },
    { title: "MLA (Ours)", body: "Low-rank KV joint compression + decoupled RoPE. Outperforms MHA with 93.3% less cache." },
  ];

  mlaPoints.forEach((p, i) => {
    const y = 1.05 + i * 1.2;
    slide4.addShape(pres.shapes.RECTANGLE, {
      x: 6.9, y, w: 2.8, h: 1.1,
      fill: { color: i === 2 ? C.darkBg : C.white }, shadow: mkShadow(0.1)
    });
    if (i === 2) {
      slide4.addShape(pres.shapes.RECTANGLE, { x: 6.9, y, w: 0.07, h: 1.1, fill: { color: C.accent } });
    }
    slide4.addText(p.title, {
      x: 7.1, y: y + 0.08, w: 2.5, h: 0.35,
      fontSize: 12, fontFace: "Arial", color: i === 2 ? C.accent : C.primary, bold: true, margin: 0
    });
    slide4.addText(p.body, {
      x: 7.1, y: y + 0.45, w: 2.5, h: 0.6,
      fontSize: 11, fontFace: "Arial", color: i === 2 ? C.white : C.text
    });
  });

  // Key insight callout at bottom
  slide4.addShape(pres.shapes.RECTANGLE, {
    x: 0.5, y: 4.75, w: 9, h: 0.7,
    fill: { color: C.darkBg }, shadow: mkShadow(0.12)
  });
  slide4.addText(
    "Key insight: Compressing K,V into a low-rank latent vector c_t^KV and reconstructing on-the-fly via learned projections yields better performance than MHA while requiring only 6.7% of the cache.",
    {
      x: 0.7, y: 4.82, w: 8.6, h: 0.56,
      fontSize: 12, fontFace: "Arial", color: C.white, valign: "middle"
    }
  );

  // ═══════════════════════════════════════════════════════════════════════════════
  // SLIDE 5 — DeepSeekMoE
  // ═══════════════════════════════════════════════════════════════════════════════
  const slide5 = pres.addSlide();
  slide5.background = { color: C.light };

  slide5.addShape(pres.shapes.RECTANGLE, { x: 0, y: 0, w: 10, h: 0.85, fill: { color: C.darkBg } });
  slide5.addText("DeepSeekMoE: Fine-Grained Experts with Shared Expert Isolation", {
    x: 0.5, y: 0.15, w: 9, h: 0.55,
    fontSize: 18, fontFace: "Arial", color: C.white, bold: true, margin: 0
  });

  // Two-column layout
  // Left: expert types
  slide5.addText("Expert Architecture", {
    x: 0.5, y: 1.05, w: 4.5, h: 0.4,
    fontSize: 14, fontFace: "Arial", color: C.primary, bold: true, margin: 0
  });

  const expertTypes = [
    {
      title: "Shared Experts (N_s)",
      body: "Always activated. Capture common knowledge shared across all tokens. Reduce redundancy in routed experts.",
      color: C.primary
    },
    {
      title: "Routed Experts (N_r)",
      body: "Sparsely activated via top-K router. Fine-grained segmentation increases specialization potential.",
      color: C.accent
    },
  ];

  expertTypes.forEach((e, i) => {
    const y = 1.5 + i * 1.35;
    slide5.addShape(pres.shapes.RECTANGLE, {
      x: 0.5, y, w: 4.5, h: 1.25,
      fill: { color: C.white }, shadow: mkShadow(0.1)
    });
