const { MdMemory, MdSpeed } = require("react-icons/md");

// ─── Palette (Ocean Gradient + Deep Tech) ───────────────────────────────────
const C = {
  darkBg:   "0B1D3A",   // deep navy
  primary:  "0D4F8B",   // ocean blue
  accent:   "00C9A7",   // teal/mint
  light:    "E8F4FD",    // ice
  white:    "FFFFFF",
  muted:    "94A3B8",
