pres.layout = "LAYOUT_16x9"; // 10 × 5.625
pres.title = "DeepSeek-V2: Efficient MoE Language Model with Multi-Head Latent Attention";
pres.author = "DeepSeek Team";

// ═══════════════════════════════════════════════════════════════════════════════
// SLIDE 1 — Title
// ═══════════════════════════════════════════════════════════════════════════════
(async () => {
  const slide1 = pres.addSlide();
