  // Top-right decorative circle
  slide1.addShape(pres.shapes.OVAL, {
    x: 7.8, y: -1.2, w: 4, h: 4,
    fill: { color: C.primary, transparency: 60 }
  });

  // Slide title
  slide1.addText("DeepSeek-V2", {
    x: 0.6, y: 1.4, w: 9, h: 1.1,
    fontSize: 52, fontFace: "Arial Black", color: C.white, bold: true
  });

  slide1.addText("Efficient MoE Language Model with\nMulti-Head Latent Attention", {
    x: 0.6, y: 2.5, w: 8.5, h: 1.0,
    fontSize: 22, fontFace: "Arial", color: C.accent
  });

  // Key stats row
  const stats = [
    { val: "236B", lbl: "Total Parameters" },
    { val: "21B", lbl: "Activated per Token" },
    { val: "128K", lbl: "Context Length" },
  ];
  stats.forEach((s, i) => {
    const x = 0.6 + i * 2.9;
    slide1.addText(s.val, {
      x, y: 3.8, w: 2.6, h: 0.7,
      fontSize: 36, fontFace: "Arial Black", color: C.accent, bold: true
    });
    slide1.addText(s.lbl, {
      x, y: 4.45, w: 2.6, h: 0.35,
      fontSize: 12, fontFace: "Arial", color: C.muted
    });
  });

  // Citation
  slide1.addText("arxiv.org/abs/2405.04434", {
    x: 0.6, y: 5.2, w: 4, h: 0.3,
    fontSize: 10, fontFace: "Arial", color: C.muted
  });

  // ═══════════════════════════════════════════════════════════════════════════════
  // SLIDE 2 — Motivation: The LLM Scaling Dilemma
