    x: chartX, y: chartY, w: chartW, h: chartH,
    fill: { color: C.white }, shadow: mkShadow(0.1)
  });

  // Grid lines (horizontal)
  for (let v = 60; v <= 80; v += 5) {
    const yPct = (v - yMin) / (yMax - yMin);
    const yPx = chartY + chartH * (1 - yPct);
    slide7.addShape(pres.shapes.LINE, {
      x: chartX, y: yPx, w: chartW, h: 0,
      line: { color: "CBD5E1", width: 0.5 }
    });
    slide7.addText(String(v), {
      x: chartX - 0.38, y: yPx - 0.12, w: 0.35, h: 0.24,
      fontSize: 9, fontFace: "Arial", color: C.muted, align: "right"
    });
  }

  // Y-axis label
  slide7.addText("MMLU Score", {
    x: chartX - 0.65, y: chartY + chartH / 2 - 0.6, w: 0.6, h: 1.2,
    fontSize: 10, fontFace: "Arial", color: C.muted, rotate: 270, align: "center"
  });

  // X-axis label
  slide7.addText("Activated Parameters (B)", {
    x: chartX, y: chartY + chartH + 0.28, w: chartW, h: 0.3,
    fontSize: 10, fontFace: "Arial", color: C.muted, align: "center"
  });

  // Model data points
  const modelColors = {
    "DeepSeek-V2":       C.accent,
    "LLaMA 3 70B":       C.primary,
    "Mixtral 8x22B":     "7C3AED",
    "Qwen1.5 72B":      "0891B2",
    "DeepSeek 67B":     "64748B",
    "LLaMA 2 70B":      "94A3B8",
    "Mixtral 8x7B":     "7C3AED",
    "LLaMA 3 8B":       "94A3B8",
  };

  scatterData[0].values.forEach(pt => {
    const xPct = (pt.x - xMin) / (xMax - xMin);
    const yPct = (pt.y - yMin) / (yMax - yMin);
    const cx = chartX + chartW * xPct;
    const cy = chartY + chartH * (1 - yPct);
    const isTarget = pt.label === "DeepSeek-V2";
    const r = isTarget ? 0.18 : 0.12;

    // Draw dot
    slide7.addShape(pres.shapes.OVAL, {
      x: cx - r, y: cy - r, w: r * 2, h: r * 2,
      fill: { color: modelColors[pt.label] || C.muted },
      line: isTarget ? { color: C.darkBg, width: 2 } : undefined
    });

    // Label (shift to avoid overlap)
    const labelOffset = isTarget ? -0.35 : (pt.y > 76 ? -0.3 : 0.15);
    slide7.addText(pt.label, {
      x: cx - 0.55, y: cy + labelOffset - 0.12, w: 1.1, h: 0.24,
      fontSize: isTarget ? 10 : 9, fontFace: "Arial",
      color: isTarget ? C.darkBg : (modelColors[pt.label] || C.muted),
      bold: isTarget, align: "center"
    });
  });

  // Pareto annotation
  slide7.addShape(pres.shapes.LINE, {
    x: chartX + chartW * ((21 - xMin) / (xMax - xMin)),
    y: chartY + chartH * (1 - (78.5 - yMin) / (yMax - yMin)),
    w: chartW * ((72 - 21) / (xMax - xMin)),
    h: -chartH * ((78.5 - 60) / (yMax - yMin)),
    line: { color: C.accent, width: 1.5, dashType: "dash" }
  });
  slide7.addText("Pareto frontier", {
    x: 5.4, y: 1.6, w: 1.3, h: 0.25,
    fontSize: 9, fontFace: "Arial", color: C.accent, italic: true
  });

  // Legend / data table on right
  slide7.addShape(pres.shapes.RECTANGLE, {
    x: 6.85, y: 1.05, w: 2.75, h: 3.8,
    fill: { color: C.white }, shadow: mkShadow(0.1)
  });
  slide7.addText("MMLU vs. Activated Params", {
    x: 7.0, y: 1.15, w: 2.5, h: 0.35,
    fontSize: 11, fontFace: "Arial", color: C.text, bold: true, margin: 0
  });

  const tableData = [
    ["Model", "Act. B", "MMLU"],
    ["DeepSeek-V2", "21", "78.5"],
    ["LLaMA 3 70B", "70", "77.0"],
    ["Mixtral 8x22B", "39", "77.6"],
    ["Qwen1.5 72B", "72", "75.6"],
    ["DeepSeek 67B", "67", "73.0"],
    ["LLaMA 2 70B", "70", "69.0"],
    ["Mixtral 8x7B", "13", "70.6"],
    ["LLaMA 3 8B", "8", "65.0"],
  ];

  tableData.forEach((row, ri) => {
    const isHeader = ri === 0;
    const rowY = 1.58 + ri * 0.36;
    if (isHeader) {
      slide7.addShape(pres.shapes.RECTANGLE, {
        x: 6.95, y: rowY - 0.03, w: 2.55, h: 0.33,
        fill: { color: C.darkBg }
      });
    }
    slide7.addText(row.join("   "), {
      x: 7.05, y: rowY, w: 2.4, h: 0.3,
      fontSize: ri === 0 ? 10 : 9.5, fontFace: "Arial",
      color: isHeader ? C.white : (ri === 1 ? C.accent : C.text),
      bold: isHeader || ri === 1
    });
  });

  // ═══════════════════════════════════════════════════════════════════════════════
  // SLIDE 8 — Alignment Results
  // ═══════════════════════════════════════════════════════════════════════════════
  const slide8 = pres.addSlide();
  slide8.background = { color: C.light };

  slide8.addShape(pres.shapes.RECTANGLE, { x: 0, y: 0, w: 10, h: 0.85, fill: { color: C.darkBg } });
  slide8.addText("DeepSeek-V2 Chat (RL) Rivals Closed-Source Models on Chinese Benchmarks", {
    x: 0.5, y: 0.15, w: 9, h: 0.55,
    fontSize: 17, fontFace: "Arial", color: C.white, bold: true, margin: 0
  });

  // Pipeline steps
  const pipeline = ["Pretraining\n8.1T tokens", "SFT\n1.5M sessions", "GRPO RL\nGroup Relative Policy Opt."];
  pipeline.forEach(async (step, i) => {
    const x = 0.5 + i * 3.15;
    slide8.addShape(pres.shapes.RECTANGLE, {
      x, y: 1.05, w: 2.9, h: 0.85,
      fill: { color: i === 2 ? C.darkBg : C.primary }
    });
    slide8.addText(step, {
      x: x + 0.1, y: 1.1, w: 2.7, h: 0.75,
      fontSize: 12, fontFace: "Arial", color: C.white, align: "center", valign: "middle"
    });
    if (i < 2) {
      slide8.addText("→", {
        x: x + 2.9, y: 1.2, w: 0.25, h: 0.55,
        fontSize: 20, fontFace: "Arial", color: C.primary, align: "center", valign: "middle"
      });
    }
  });

  // Benchmark score cards
  const benchmarks = [
    { name: "AlpacaEval 2.0", score: "38.9%", note: "Length-controlled win rate", detail: "Outperforms most open-source" },
    { name: "MT-Bench", score: "8.97", note: "Overall score", detail: "Competitive with closed models" },
    { name: "AlignBench", score: "7.91", note: "Chinese overall", detail: "Best open-source in Chinese" },
  ];

  benchmarks.forEach(async (b, i) => {
    const x = 0.5 + i * 3.15;
    slide8.addShape(pres.shapes.RECTANGLE, {
      x, y: 2.15, w: 2.9, h: 2.6,
      fill: { color: C.white }, shadow: mkShadow(0.12)
    });
    slide8.addShape(pres.shapes.RECTANGLE, { x, y: 2.15, w: 2.9, h: 0.06, fill: { color: C.accent } });

    slide8.addText(b.name, {
      x: x + 0.15, y: 2.3, w: 2.6, h: 0.35,
      fontSize: 13, fontFace: "Arial", color: C.primary, bold: true, margin: 0
    });
    slide8.addText(b.note, {
      x: x + 0.15, y: 2.65, w: 2.6, h: 0.28,
      fontSize: 10, fontFace: "Arial", color: C.muted, margin: 0
    });
    slide8.addText(b.score, {
      x: x + 0.15, y: 3.0, w: 2.6, h: 0.85,
      fontSize: 44, fontFace: "Arial Black", color: C.darkBg, bold: true
    });
    slide8.addText(b.detail, {
      x: x + 0.15, y: 3.95, w: 2.6, h: 0.6,
      fontSize: 11, fontFace: "Arial", color: C.accent, italic: true
    });
  });

  // Bottom note
  slide8.addShape(pres.shapes.RECTANGLE, {
    x: 0.5, y: 4.9, w: 9, h: 0.6,
    fill: { color: C.darkBg }, shadow: mkShadow(0.1)
  });
  slide8.addText(
    "On AlignBench (Chinese), DeepSeek-V2 Chat (RL) outperforms all open-source and most closed-source models.",
    {
      x: 0.7, y: 4.97, w: 8.6, h: 0.46,
      fontSize: 12, fontFace: "Arial", color: C.accent, valign: "middle"
    }
  );

  // ═══════════════════════════════════════════════════════════════════════════════
  // SLIDE 9 — Takeaways
  // ═══════════════════════════════════════════════════════════════════════════════
  const slide9 = pres.addSlide();
  slide9.background = { color: C.darkBg };

  // Left accent bar
  slide9.addShape(pres.shapes.RECTANGLE, { x: 0, y: 0, w: 0.12, h: 5.625, fill: { color: C.accent } });

  slide9.addText("Key Takeaways", {
    x: 0.6, y: 0.35, w: 9, h: 0.7,
    fontSize: 32, fontFace: "Arial Black", color: C.white, bold: true
  });
  slide9.addText("Architectural Innovation Unlocks Efficient Scaling", {
    x: 0.6, y: 0.95, w: 9, h: 0.4,
    fontSize: 16, fontFace: "Arial", color: C.accent
  });

  const takeaways = [
    { icon: FaCheckCircle, text: "MLA achieves superior performance to MHA while reducing KV cache by 93.3% — a strictly better alternative to GQA/MQA for inference efficiency." },
    { icon: FaCheckCircle, text: "DeepSeekMoE with fine-grained experts and shared expert isolation enables training a 236B-parameter model at 42.5% lower cost than a 67B dense model." },
    { icon: FaCheckCircle, text: "Only 21B activated parameters are needed to match or exceed 70B-class dense models (LLaMA 3 70B, Qwen1.5 72B) on MMLU." },
    { icon: FaCheckCircle, text: "5.76× generation throughput improvement over DeepSeek 67B makes DeepSeek-V2 practical for large-scale deployment." },
    { icon: FaCheckCircle, text: "DeepSeek-V2 Chat (RL) is the strongest open-source chat model in Chinese and competitive with closed-source systems in English open-ended evaluation." },
  ];

  takeaways.forEach(async (t, i) => {
    const y = 1.5 + i * 0.78;
    const iconImg = await iconPng(t.icon, "#" + C.accent, 256);
    slide9.addImage({ data: iconImg, x: 0.6, y: y + 0.08, w: 0.38, h: 0.38 });
    slide9.addText(t.text, {
      x: 1.15, y: y, w: 8.2, h: 0.7,
      fontSize: 13, fontFace: "Arial", color: C.white, valign: "middle"
    });
  });

  // Footer
  slide9.addShape(pres.shapes.RECTANGLE, { x: 0.6, y: 5.3, w: 8.8, h: 0.01, fill: { color: C.primary } });
  slide9.addText("DeepSeek-V2  •  arxiv.org/abs/2405.04434  •  Open-source available", {
    x: 0.6, y: 5.35, w: 9, h: 0.25,
    fontSize: 10, fontFace: "Arial", color: C.muted
  });

  // ─── Write file ──────────────────────────────────────────────────────────────
  await pres.writeFile({ fileName: "/app/output/final_deck.pptx" });
  console.log("Done: /app/output/final_deck.pptx");
