const pptxgen = require("pptxgenjs");
const React = require("react");
const ReactDOMServer = require("react-dom/server");
const sharp = require("sharp");
const { FaBrain, FaChartBar, FaBolt, FaCubes, FaCheckCircle, FaArrowRight, FaMicrochip } = require("react-icons/fa");
const { MdMemory, MdSpeed } = require("react-icons/md");

// ─── Palette ─────────────────────────────────────────────────────────────────
const C = {
  darkBg:   "0B1D3A",
  primary:  "0D4F8B",
  accent:   "00C9A7",
  light:    "E8F4FD",
  white:    "FFFFFF",
  muted:    "94A3B8",
  text:     "1E293B",
  cardBg:   "112240",
  cardLight:"F8FAFC",
  orange:   "FB923C",
};

// ─── Icon helper ───────────────────────────────────────────────────────────────
async function iconPng(IconComp, color = "#FFFFFF", size = 256) {
  const svg = ReactDOMServer.renderToStaticMarkup(
    React.createElement(IconComp, { color, size: String(size) })
  );
  const buf = await sharp(Buffer.from(svg)).png().toBuffer();
  return "image/png;base64," + buf.toString("base64");
}

// ─── Shadow factory ───────────────────────────────────────────────────────────
const mkShadow = (opacity = 0.18) => ({ type: "outer", blur: 8, offset: 3, angle: 135, color: "000000", opacity });

// ─── Presentation ─────────────────────────────────────────────────────────────
const pres = new pptxgen();
pres.layout = "LAYOUT_16x9";
pres.title = "DeepSeek-V2: Efficient MoE Language Model with Multi-Head Latent Attention";
pres.author = "DeepSeek Team";

// ═══════════════════════════════════════════════════════════════════════════════
// SLIDE 1 — Title
// ═══════════════════════════════════════════════════════════════════════════════
const slide1 = pres.addSlide();
slide1.background = { color: C.darkBg };

slide1.addShape(pres.shapes.RECTANGLE, { x: 0, y: 0, w: 0.12, h: 5.625, fill: { color: C.accent } });
slide1.addShape(pres.shapes.OVAL, { x: 7.8, y: -1.2, w: 4, h: 4, fill: { color: C.primary, transparency: 60 } });

slide1.addText("DeepSeek-V2", {
  x: 0.6, y: 1.4, w: 9, h: 1.1,
  fontSize: 52, fontFace: "Arial Black", color: C.white, bold: true
});
slide1.addText("Efficient MoE Language Model with\nMulti-Head Latent Attention", {
  x: 0.6, y: 2.5, w: 8.5, h: 1.0, fontSize: 22, fontFace: "Arial", color: C.accent
});

const stats = [
  { val: "236B", lbl: "Total Parameters" },
  { val: "21B", lbl: "Activated per Token" },
  { val: "128K", lbl: "Context Length" },
];
stats.forEach((s, i) => {
  const x = 0.6 + i * 2.9;
  slide1.addText(s.val, { x, y: 3.8, w: 2.6, h: 0.7, fontSize: 36, fontFace: "Arial Black", color: C.accent, bold: true });
  slide1.addText(s.lbl, { x, y: 4.45, w: 2.6, h: 0.35, fontSize: 12, fontFace: "Arial", color: C.muted });
});

slide1.addText("arxiv.org/abs/2405.04434", { x: 0.6, y: 5.2, w: 4, h: 0.3, fontSize: 10, fontFace: "Arial", color: C.muted });

// ═══════════════════════════════════════════════════════════════════════════════
// SLIDE 2 — Motivation
// ═══════════════════════════════════════════════════════════════════════════════
const slide2 = pres.addSlide();
slide2.background = { color: C.light };

slide2.addShape(pres.shapes.RECTANGLE, { x: 0, y: 0, w: 10, h: 0.85, fill: { color: C.darkBg } });
slide2.addText("The LLM Scaling Dilemma: Performance vs. Training Cost and Inference Speed", {
  x: 0.5, y: 0.15, w: 9, h: 0.55,
  fontSize: 17, fontFace: "Arial", color: C.white, bold: true, margin: 0
});

slide2.addShape(pres.shapes.RECTANGLE, { x: 0.5, y: 1.1, w: 9, h: 1.1, fill: { color: C.darkBg }, shadow: mkShadow(0.15) });
slide2.addText(
  "Larger dense models yield better intelligence but incur prohibitive training costs and slow inference due to KV cache bottlenecks.",
  { x: 0.7, y: 1.2, w: 8.6, h: 0.9, fontSize: 15, fontFace: "Arial", color: C.white, valign: "middle" }
);

const challenges = [
  { icon: FaBrain, title: "Performance Trap", body: "Scaling dense models improves benchmarks but grows compute at O(N) for every activated parameter." },
  { icon: FaBolt, title: "Training Cost", body: "Pretraining a 70B dense model costs tens of millions of dollars, limiting who can afford to train." },
  { icon: MdMemory, title: "KV Cache Bottleneck", body: "Standard MHA caches full key-value pairs per head per token, making long-context inference memory-bound." },
];

for (const [i, c] of challenges.entries()) {
  const x = 0.5 + i * 3.1;
  slide2.addShape(pres.shapes.RECTANGLE, { x, y: 2.45, w: 2.9, h: 2.75, fill: { color: C.white }, shadow: mkShadow(0.12) });
}

slide2.addShape(pres.shapes.RECTANGLE, { x: 0.5, y: 2.45, w: 2.9, h: 2.75, fill: { color: C.white }, shadow: mkShadow(0.12) });
slide2.addShape(pres.shapes.RECTANGLE, { x: 3.6, y: 2.45, w: 2.9, h: 2.75, fill: { color: C.white }, shadow: mkShadow(0.12) });
slide2.addShape(pres.shapes.RECTANGLE, { x: 6.7, y: 2.45, w: 2.9, h: 2.75, fill: { color: C.white }, shadow: mkShadow(0.12) });

const iconBrain  = await iconPng(FaBrain, "#" + C.accent, 256);
const iconBolt   = await iconPng(FaBolt,  "#" + C.accent, 256);
const iconMemory = await iconPng(MdMemory, "#" + C.accent, 256);

const iconImgs = [iconBrain, iconBolt, iconMemory];
for (const [i, c] of challenges.entries()) {
  const x = 0.5 + i * 3.1;
  slide2.addImage({ data: iconImgs[i], x: x + 0.15, y: 2.6, w: 0.5, h: 0.5 });
  slide2.addText(c.title, { x: x + 0.75, y: 2.62, w: 2.0, h: 0.45, fontSize: 14, fontFace: "Arial", color: C.text, bold: true, valign: "middle", margin: 0 });
  slide2.addText(c.body, { x: x + 0.15, y: 3.2, w: 2.6, h: 1.8, fontSize: 12, fontFace: "Arial", color: C.text });
}

slide2.addShape(pres.shapes.RECTANGLE, { x: 0.5, y: 5.25, w: 9, h: 0.02, fill: { color: C.accent } });
slide2.addText("→  MoE + efficient attention are needed to break the cost-performance trade-off", {
  x: 0.5, y: 5.3, w: 9, h: 0.28, fontSize: 12, fontFace: "Arial", color: C.primary, italic: true
});

// ═══════════════════════════════════════════════════════════════════════════════
// SLIDE 3 — Architecture Overview
// ═══════════════════════════════════════════════════════════════════════════════
const slide3 = pres.addSlide();
slide3.background = { color: C.light };

slide3.addShape(pres.shapes.RECTANGLE, { x: 0, y: 0, w: 10, h: 0.85, fill: { color: C.darkBg } });
slide3.addText("DeepSeek-V2 Architecture: MLA + DeepSeekMoE in a Transformer Block", {
  x: 0.5, y: 0.15, w: 9, h: 0.55, fontSize: 17, fontFace: "Arial", color: C.white, bold: true, margin: 0
});

const fig1Data = await sharp("/app/benchmark/assets/figure_1.jpg").resize({ width: 900 }).jpeg({ quality: 88 }).toBuffer();
slide3.addImage({ data: "image/jpeg;base64," + fig1Data.toString("base64"), x: 0.5, y: 1.0, w: 9, h: 3.4 });
slide3.addText("Figure 1: DeepSeek-V2 block with Multi-Head Latent Attention (MLA) and DeepSeekMoE replacing standard attention and dense FFN.", {
  x: 0.5, y: 4.5, w: 9, h: 0.3, fontSize: 10, fontFace: "Arial", color: C.muted, italic: true
});

slide3.addShape(pres.shapes.RECTANGLE, { x: 0.5, y: 4.9, w: 4.3, h: 0.6, fill: { color: C.cardLight }, shadow: mkShadow(0.1) });
slide3.addShape(pres.shapes.RECTANGLE, { x: 0.5, y: 4.9, w: 0.07, h: 0.6, fill: { color: C.accent } });
slide3.addText("MLA replaces standard MHA: low-rank KV compression → 93.3% cache reduction", {
  x: 0.7, y: 4.95, w: 4.0, h: 0.5, fontSize: 11, fontFace: "Arial", color: C.text, valign: "middle"
});

slide3.addShape(pres.shapes.RECTANGLE, { x: 5.2, y: 4.9, w: 4.3, h: 0.6, fill: { color: C.cardLight }, shadow: mkShadow(0.1) });
slide3.addShape(pres.shapes.RECTANGLE, { x: 5.2, y: 4.9, w: 0.07, h: 0.6, fill: { color: C.primary } });
slide3.addText("DeepSeekMoE replaces dense FFN: shared + routed experts, top-K routing", {
  x: 5.4, y: 4.95, w: 4.0, h: 0.5, fontSize: 11, fontFace: "Arial", color: C.text, valign: "middle"
});

// ═══════════════════════════════════════════════════════════════════════════════
// SLIDE 4 — MLA Mechanism
// ═══════════════════════════════════════════════════════════════════════════════
const slide4 = pres.addSlide();
slide4.background = { color: C.light };

slide4.addShape(pres.shapes.RECTANGLE, { x: 0, y: 0, w: 10, h: 0.85, fill: { color: C.darkBg } });
slide4.addText("Multi-Head Latent Attention Compresses KV Cache by 93.3%", {
  x: 0.5, y: 0.15, w: 9, h: 0.55, fontSize: 18, fontFace: "Arial", color: C.white, bold: true, margin: 0
});

const fig2Data = await sharp("/app/benchmark/assets/figure_2.jpg").resize({ width: 900 }).jpeg({ quality: 88 }).toBuffer();
slide4.addImage({ data: "image/jpeg;base64," + fig2Data.toString("base64"), x: 0.5, y: 1.0, w: 6.2, h: 3.6 });

const mlaPoints = [
  { title: "MHA (Baseline)", body: "Full K,V per head per token. High memory, best quality." },
  { title: "GQA / MQA", body: "Shared K,V across heads. Less cache but degraded quality." },
  { title: "MLA (Ours)", body: "Low-rank KV joint compression + decoupled RoPE. Outperforms MHA with 93.3% less cache." },
];

for (const [i, p] of mlaPoints.entries()) {
  const y = 1.05 + i * 1.2;
  const isMla = i === 2;
  slide4.addShape(pres.shapes.RECTANGLE, { x: 6.9, y, w: 2.8, h: 1.1, fill: { color: isMla ? C.darkBg : C.white }, shadow: mkShadow(0.1) });
  if (isMla) slide4.addShape(pres.shapes.RECTANGLE, { x: 6.9, y, w: 0.07, h: 1.1, fill: { color: C.accent } });
