const pptxgen = require("pptxgenjs");
const React = require("react");
const ReactDOMServer = require("react-dom/server");
const sharp = require("sharp");
const { FaBrain, FaChartBar, FaBolt, FaCubes, FaCheckCircle, FaArrowRight, FaMicrochip } = require("react-icons/fa");
const { MdMemory, MdSpeed } = require("react-icons/md");

// ─── Palette ─────────────────────────────────────────────────────────────────
const C = {
  darkBg:   "0B1D3A",
  primary:  "0D4F8B",
  accent:   "00C9A7",
  light:    "E8F4FD",
  white:    "FFFFFF",
  muted:    "94A3B8",
  text:     "1E293B",
  cardBg:   "112240",
  cardLight:"F8FAFC",
  orange:   "FB923C",
};

// ─── Icon helper ───────────────────────────────────────────────────────────────
async function iconPng(IconComp, color = "#FFFFFF", size = 256) {
  const svg = ReactDOMServer.renderToStaticMarkup(
    React.createElement(IconComp, { color, size: String(size) })
  );
  const buf = await sharp(Buffer.from(svg)).png().toBuffer();
  return "image/png;base64," + buf.toString("base64");
}

// ─── Shadow factory ───────────────────────────────────────────────────────────
const mkShadow = (opacity = 0.18) => ({ type: "outer", blur: 8, offset: 3, angle: 135, color: "000000", opacity });

// ─── Presentation ─────────────────────────────────────────────────────────────
const pres = new pptxgen();
pres.layout = "LAYOUT_16x9";
pres.title = "DeepSeek-V2: Efficient MoE Language Model with Multi-Head Latent Attention";
pres.author = "DeepSeek Team";

// ═══════════════════════════════════════════════════════════════════════════════
// SLIDE 1 — Title
// ═══════════════════════════════════════════════════════════════════════════════
const slide1 = pres.addSlide();
slide1.background = { color: C.darkBg };

slide1.addShape(pres.shapes.RECTANGLE, { x: 0, y: 0, w: 0.12, h: 5.625, fill: { color: C.accent } });
slide1.addShape(pres.shapes.OVAL, { x: 7.8, y: -1.2, w: 4, h: 4, fill: { color: C.primary, transparency: 60 } });

slide1.addText("DeepSeek-V2", {
  x: 0.6, y: 1.4, w: 9, h: 1.1,
  fontSize: 52, fontFace: "Arial Black", color: C.white, bold: true
});
slide1.addText("Efficient MoE Language Model with\nMulti-Head Latent Attention", {
  x: 0.6, y: 2.5, w: 8.5, h: 1.0, fontSize: 22, fontFace: "Arial", color: C.accent
});

const stats = [
  { val: "236B", lbl: "Total Parameters" },
  { val: "21B", lbl: "Activated per Token" },
  { val: "128K", lbl: "Context Length" },
];
stats.forEach((s, i) => {
  const x = 0.6 + i * 2.9;
  slide1.addText(s.val, { x, y: 3.8, w: 2.6, h: 0.7, fontSize: 36, fontFace: "Arial Black", color: C.accent, bold: true });
  slide1.addText(s.lbl, { x, y: 4.45, w: 2.6, h: 0.35, fontSize: 12, fontFace: "Arial", color: C.muted });
});

slide1.addText("arxiv.org/abs/2405.04434", { x: 0.6, y: 5.2, w: 4, h: 0.3, fontSize: 10, fontFace: "Arial", color: C.muted });

// ═══════════════════════════════════════════════════════════════════════════════
// SLIDE 2 — Motivation
// ═══════════════════════════════════════════════════════════════════════════════
const slide2 = pres.addSlide();
slide2.background = { color: C.light };

slide2.addShape(pres.shapes.RECTANGLE, { x: 0, y: 0, w: 10, h: 0.85, fill: { color: C.darkBg } });
slide2.addText("The LLM Scaling Dilemma: Performance vs. Training Cost and Inference Speed", {
  x: 0.5, y: 0.15, w: 9, h: 0.55,
  fontSize: 17, fontFace: "Arial", color: C.white, bold: true, margin: 0
});

slide2.addShape(pres.shapes.RECTANGLE, { x: 0.5, y: 1.1, w: 9, h: 1.1, fill: { color: C.darkBg }, shadow: mkShadow(0.15) });
slide2.addText(
  "Larger dense models yield better intelligence but incur prohibitive training costs and slow inference due to KV cache bottlenecks.",
  { x: 0.7, y: 1.2, w: 8.6, h: 0.9, fontSize: 15, fontFace: "Arial", color: C.white, valign: "middle" }
);

const challenges = [
  { icon: FaBrain, title: "Performance Trap", body: "Scaling dense models improves benchmarks but grows compute at O(N) for every activated parameter." },
  { icon: FaBolt, title: "Training Cost", body: "Pretraining a 70B dense model costs tens of millions of dollars, limiting who can afford to train." },
  { icon: MdMemory, title: "KV Cache Bottleneck", body: "Standard MHA caches full key-value pairs per head per token, making long-context inference memory-bound." },
];

for (const [i, c] of challenges.entries()) {
  const x = 0.5 + i * 3.1;
  slide2.addShape(pres.shapes.RECTANGLE, { x, y: 2.45, w: 2.9, h: 2.75, fill: { color: C.white }, shadow: mkShadow(0.12) });
}

slide2.addShape(pres.shapes.RECTANGLE, { x: 0.5, y: 2.45, w: 2.9, h: 2.75, fill: { color: C.white }, shadow: mkShadow(0.12) });
slide2.addShape(pres.shapes.RECTANGLE, { x: 3.6, y: 2.45, w: 2.9, h: 2.75, fill: { color: C.white }, shadow: mkShadow(0.12) });
slide2.addShape(pres.shapes.RECTANGLE, { x: 6.7, y: 2.45, w: 2.9, h: 2.75, fill: { color: C.white }, shadow: mkShadow(0.12) });

const iconBrain  = await iconPng(FaBrain, "#" + C.accent, 256);
const iconBolt   = await iconPng(FaBolt,  "#" + C.accent, 256);
const iconMemory = await iconPng(MdMemory, "#" + C.accent, 256);

const iconImgs = [iconBrain, iconBolt, iconMemory];
for (const [i, c] of challenges.entries()) {
  const x = 0.5 + i * 3.1;
  slide2.addImage({ data: iconImgs[i], x: x + 0.15, y: 2.6, w: 0.5, h: 0.5 });
  slide2.addText(c.title, { x: x + 0.75, y: 2.62, w: 2.0, h: 0.45, fontSize: 14, fontFace: "Arial", color: C.text, bold: true, valign: "middle", margin: 0 });
  slide2.addText(c.body, { x: x + 0.15, y: 3.2, w: 2.6, h: 1.8, fontSize: 12, fontFace: "Arial", color: C.text });
}

slide2.addShape(pres.shapes.RECTANGLE, { x: 0.5, y: 5.25, w: 9, h: 0.02, fill: { color: C.accent } });
slide2.addText("→  MoE + efficient attention are needed to break the cost-performance trade-off", {
  x: 0.5, y: 5.3, w: 9, h: 0.28, fontSize: 12, fontFace: "Arial", color: C.primary, italic: true
});

// ═══════════════════════════════════════════════════════════════════════════════
// SLIDE 3 — Architecture Overview
// ═══════════════════════════════════════════════════════════════════════════════
const slide3 = pres.addSlide();
slide3.background = { color: C.light };

slide3.addShape(pres.shapes.RECTANGLE, { x: 0, y: 0, w: 10, h: 0.85, fill: { color: C.darkBg } });
slide3.addText("DeepSeek-V2 Architecture: MLA + DeepSeekMoE in a Transformer Block", {
  x: 0.5, y: 0.15, w: 9, h: 0.55, fontSize: 17, fontFace: "Arial", color: C.white, bold: true, margin: 0
});

const fig1Data = await sharp("/app/benchmark/assets/figure_1.jpg").resize({ width: 900 }).jpeg({ quality: 88 }).toBuffer();
slide3.addImage({ data: "image/jpeg;base64," + fig1Data.toString("base64"), x: 0.5, y: 1.0, w: 9, h: 3.4 });
slide3.addText("Figure 1: DeepSeek-V2 block with Multi-Head Latent Attention (MLA) and DeepSeekMoE replacing standard attention and dense FFN.", {
  x: 0.5, y: 4.5, w: 9, h: 0.3, fontSize: 10, fontFace: "Arial", color: C.muted, italic: true
});

slide3.addShape(pres.shapes.RECTANGLE, { x: 0.5, y: 4.9, w: 4.3, h: 0.6, fill: { color: C.cardLight }, shadow: mkShadow(0.1) });
slide3.addShape(pres.shapes.RECTANGLE, { x: 0.5, y: 4.9, w: 0.07, h: 0.6, fill: { color: C.accent } });
slide3.addText("MLA replaces standard MHA: low-rank KV compression → 93.3% cache reduction", {
  x: 0.7, y: 4.95, w: 4.0, h: 0.5, fontSize: 11, fontFace: "Arial", color: C.text, valign: "middle"
});

slide3.addShape(pres.shapes.RECTANGLE, { x: 5.2, y: 4.9, w: 4.3, h: 0.6, fill: { color: C.cardLight }, shadow: mkShadow(0.1) });
slide3.addShape(pres.shapes.RECTANGLE, { x: 5.2, y: 4.9, w: 0.07, h: 0.6, fill: { color: C.primary } });
slide3.addText("DeepSeekMoE replaces dense FFN: shared + routed experts, top-K routing", {
  x: 5.4, y: 4.95, w: 4.0, h: 0.5, fontSize: 11, fontFace: "Arial", color: C.text, valign: "middle"
});

// ═══════════════════════════════════════════════════════════════════════════════
// SLIDE 4 — MLA Mechanism
// ═══════════════════════════════════════════════════════════════════════════════
const slide4 = pres.addSlide();
slide4.background = { color: C.light };

slide4.addShape(pres.shapes.RECTANGLE, { x: 0, y: 0, w: 10, h: 0.85, fill: { color: C.darkBg } });
slide4.addText("Multi-Head Latent Attention Compresses KV Cache by 93.3%", {
  x: 0.5, y: 0.15, w: 9, h: 0.55, fontSize: 18, fontFace: "Arial", color: C.white, bold: true, margin: 0
});

const fig2Data = await sharp("/app/benchmark/assets/figure_2.jpg").resize({ width: 900 }).jpeg({ quality: 88 }).toBuffer();
slide4.addImage({ data: "image/jpeg;base64," + fig2Data.toString("base64"), x: 0.5, y: 1.0, w: 6.2, h: 3.6 });

const mlaPoints = [
  { title: "MHA (Baseline)", body: "Full K,V per head per token. High memory, best quality." },
  { title: "GQA / MQA", body: "Shared K,V across heads. Less cache but degraded quality." },
  { title: "MLA (Ours)", body: "Low-rank KV joint compression + decoupled RoPE. Outperforms MHA with 93.3% less cache." },
];

for (const [i, p] of mlaPoints.entries()) {
  const y = 1.05 + i * 1.2;
  const isMla = i === 2;
  slide4.addShape(pres.shapes.RECTANGLE, { x: 6.9, y, w: 2.8, h: 1.1, fill: { color: isMla ? C.darkBg : C.white }, shadow: mkShadow(0.1) });
  if (isMla) slide4.addShape(pres.shapes.RECTANGLE, { x: 6.9, y, w: 0.07, h: 1.1, fill: { color: C.accent } });
  slide4.addText(p.title, { x: 7.1, y: y + 0.08, w: 2.5, h: 0.35, fontSize: 12, fontFace: "Arial", color: isMla ? C.accent : C.primary, bold: true, margin: 0 });
  slide4.addText(p.body, { x: 7.1, y: y + 0.45, w: 2.5, h: 0.6, fontSize: 11, fontFace: "Arial", color: isMla ? C.white : C.text });
}

slide4.addShape(pres.shapes.RECTANGLE, { x: 0.5, y: 4.75, w: 9, h: 0.7, fill: { color: C.darkBg }, shadow: mkShadow(0.12) });
slide4.addText("Key insight: Compressing K,V into a low-rank latent vector c_t^KV and reconstructing on-the-fly via learned projections yields better performance than MHA while requiring only 6.7% of the cache.", {
  x: 0.7, y: 4.82, w: 8.6, h: 0.56, fontSize: 12, fontFace: "Arial", color: C.white, valign: "middle"
});

// ═══════════════════════════════════════════════════════════════════════════════
// SLIDE 5 — DeepSeekMoE
// ═══════════════════════════════════════════════════════════════════════════════
const slide5 = pres.addSlide();
slide5.background = { color: C.light };

slide5.addShape(pres.shapes.RECTANGLE, { x: 0, y: 0, w: 10, h: 0.85, fill: { color: C.darkBg } });
slide5.addText("DeepSeekMoE: Fine-Grained Experts with Shared Expert Isolation", {
  x: 0.5, y: 0.15, w: 9, h: 0.55, fontSize: 18, fontFace: "Arial", color: C.white, bold: true, margin: 0
});

slide5.addText("Expert Architecture", { x: 0.5, y: 1.05, w: 4.5, h: 0.4, fontSize: 14, fontFace: "Arial", color: C.primary, bold: true, margin: 0 });

const expertTypes = [
  { title: "Shared Experts (N_s)", body: "Always activated. Capture common knowledge shared across all tokens. Reduce redundancy in routed experts.", color: C.primary },
  { title: "Routed Experts (N_r)", body: "Sparsely activated via top-K router. Fine-grained segmentation increases specialization potential.", color: C.accent },
];

for (const [i, e] of expertTypes.entries()) {
  const y = 1.5 + i * 1.35;
  slide5.addShape(pres.shapes.RECTANGLE, { x: 0.5, y, w: 4.5, h: 1.25, fill: { color: C.white }, shadow: mkShadow(0.1) });
  slide5.addShape(pres.shapes.RECTANGLE, { x: 0.5, y, w: 0.08, h: 1.25, fill: { color: e.color } });
  slide5.addText(e.title, { x: 0.72, y: y + 0.1, w: 4.1, h: 0.35, fontSize: 13, fontFace: "Arial", color: e.color, bold: true, margin: 0 });
  slide5.addText(e.body, { x: 0.72, y: y + 0.5, w: 4.1, h: 0.7, fontSize: 11, fontFace: "Arial", color: C.text });
}

slide5.addText("Training Efficiency Mechanisms", { x: 5.2, y: 1.05, w: 4.5, h: 0.4, fontSize: 14, fontFace: "Arial", color: C.primary, bold: true, margin: 0 });

const mechPoints = [
  { icon: FaCubes, text: "Fine-grained expert segmentation increases specialization granularity" },
  { icon: FaMicrochip, text: "Device-limited routing: each token sent to experts on ≤ M devices → reduces cross-node communication" },
  { icon: FaArrowRight, text: "Auxiliary load-balancing losses prevent expert collapse" },
  { icon: FaBolt, text: "Token-dropping strategy during training prevents expert overflow (inference unchanged)" },
];

const mechIcons = await Promise.all(mechPoints.map(m => iconPng(m.icon, "#" + C.accent, 256)));
for (const [i, m] of mechPoints.entries()) {
  const y = 1.5 + i * 0.92;
  slide5.addShape(pres.shapes.RECTANGLE, { x: 5.2, y, w: 4.3, h: 0.84, fill: { color: C.white }, shadow: mkShadow(0.1) });
  slide5.addImage({ data: mechIcons[i], x: 5.35, y: y + 0.17, w: 0.45, h: 0.45 });
  slide5.addText(m.text, { x: 5.95, y: y + 0.08, w: 3.4, h: 0.68, fontSize: 11, fontFace: "Arial", color: C.text, valign: "middle" });
}

slide5.addShape(pres.shapes.RECTANGLE, { x: 0.5, y: 4.9, w: 9, h: 0.6, fill: { color: C.darkBg }, shadow: mkShadow(0.12) });
slide5.addText("Result: 236B total parameters — activating only 21B per token — trained at 42.5% lower cost than DeepSeek 67B dense model", {
  x: 0.7, y: 4.97, w: 8.6, h: 0.46, fontSize: 12, fontFace: "Arial", color: C.accent, valign: "middle", bold: true
});

// ═══════════════════════════════════════════════════════════════════════════════
// SLIDE 6 — Efficiency Gains
// ═══════════════════════════════════════════════════════════════════════════════
const slide6 = pres.addSlide();
slide6.background = { color: C.darkBg };

slide6.addText("42.5% Training Cost Reduction & 5.76× Throughput vs. DeepSeek 67B", {
  x: 0.5, y: 0.2, w: 9, h: 0.6, fontSize: 20, fontFace: "Arial", color: C.white, bold: true
});
slide6.addText("DeepSeek-V2 relative efficiency gains over its dense predecessor", {
  x: 0.5, y: 0.78, w: 9, h: 0.3, fontSize: 13, fontFace: "Arial", color: C.muted
});

const metrics = [
  { pct: "42.5%", label: "Training Cost\nReduction", sub: "vs. DeepSeek 67B", icon: FaBolt, color: C.accent },
  { pct: "93.3%", label: "KV Cache\nReduction", sub: "vs. DeepSeek 67B", icon: MdMemory, color: C.accent },
  { pct: "5.76×", label: "Generation\nThroughput", sub: "max vs. DeepSeek 67B", icon: MdSpeed, color: C.orange },
];

const metricIcons = await Promise.all(metrics.map(m => iconPng(m.icon, "#" + m.color, 256)));
for (const [i, m] of metrics.entries()) {
  const x = 0.5 + i * 3.15;
  slide6.addShape(pres.shapes.RECTANGLE, { x, y: 1.25, w: 2.95, h: 3.6, fill: { color: C.cardBg }, shadow: mkShadow(0.2) });
  slide6.addShape(pres.shapes.RECTANGLE, { x, y: 1.25, w: 2.95, h: 0.06, fill: { color: m.color } });
  slide6.addImage({ data: metricIcons[i], x: x + 1.1, y: 1.5, w: 0.75, h: 0.75 });
  slide6.addText(m.pct, { x: x + 0.1, y: 2.35, w: 2.75, h: 1.0, fontSize: 48, fontFace: "Arial Black", color: m.color, bold: true, align: "center" });
  slide6.addText(m.label, { x: x + 0.1, y: 3.4, w: 2.75, h: 0.75, fontSize: 15, fontFace: "Arial", color: C.white, bold: true, align: "center" });
  slide6.addText(m.sub, { x: x + 0.1, y: 4.2, w: 2.75, h: 0.4, fontSize: 11, fontFace: "Arial", color: C.muted, align: "center" });
}

slide6.addShape(pres.shapes.RECTANGLE, { x: 0.5, y: 5.0, w: 9, h: 0.02, fill: { color: C.primary } });
slide6.addText("No absolute FLOPs or absolute cache values fabricated — all metrics are relative improvements over DeepSeek 67B as reported.", {
  x: 0.5, y: 5.1, w: 9, h: 0.3, fontSize: 9, fontFace: "Arial", color: C.muted, italic: true
});

// ═══════════════════════════════════════════════════════════════════════════════
// SLIDE 7 — MMLU Performance Comparison
// ═══════════════════════════════════════════════════════════════════════════════
const slide7 = pres.addSlide();
slide7.background = { color: C.light };

slide7.addShape(pres.shapes.RECTANGLE, { x: 0, y: 0, w: 10, h: 0.85, fill: { color: C.darkBg } });
slide7.addText("DeepSeek-V2 Tops MMLU Among Open-Source Models at Only 21B Activated Parameters", {
  x: 0.5, y: 0.15, w: 9, h: 0.55, fontSize: 15, fontFace: "Arial", color: C.white, bold: true, margin: 0
});

const chartX = 0.6, chartY = 1.05, chartW = 6.0, chartH = 3.8;
const xMin = 0, xMax = 80, yMin = 60, yMax = 82;

slide7.addShape(pres.shapes.RECTANGLE, { x: chartX, y: chartY, w: chartW, h: chartH, fill: { color: C.white }, shadow: mkShadow(0.1) });

for (let v = 60; v <= 80; v += 5) {
  const yPct = (v - yMin) / (yMax - yMin);
  const yPx = chartY + chartH * (1 - yPct);
  slide7.addShape(pres.shapes.LINE, { x: chartX, y: yPx, w: chartW, h: 0, line: { color: "CBD5E1", width: 0.5 } });
  slide7.addText(String(v), { x: chartX - 0.38, y: yPx - 0.12, w: 0.35, h: 0.24, fontSize: 9, fontFace: "Arial", color: C.muted, align: "right" });
}

slide7.addText("MMLU Score", { x: chartX - 0.65, y: chartY + chartH / 2 - 0.6, w: 0.6, h: 1.2, fontSize: 10, fontFace: "Arial", color: C.muted, rotate: 270, align: "center" });
slide7.addText("Activated Parameters (B)", { x: chartX, y: chartY + chartH + 0.28, w: chartW, h: 0.3, fontSize: 10, fontFace: "Arial", color: C.muted, align: "center" });

const modelColors = {
  "DeepSeek-V2":       C.accent,
  "LLaMA 3 70B":      C.primary,
  "Mixtral 8x22B":    "7C3AED",
  "Qwen1.5 72B":      "0891B2",
  "DeepSeek 67B":     "64748B",
  "LLaMA 2 70B":      "94A3B8",
  "Mixtral 8x7B":     "7C3AED",
  "LLaMA 3 8B":       "94A3B8",
};

const scatterPts = [
  { x: 21,  y: 78.5, label: "DeepSeek-V2" },
  { x: 70,  y: 77.0, label: "LLaMA 3 70B" },
  { x: 39,  y: 77.6, label: "Mixtral 8x22B" },
  { x: 72,  y: 75.6, label: "Qwen1.5 72B" },
  { x: 67,  y: 73.0, label: "DeepSeek 67B" },
  { x: 70,  y: 69.0, label: "LLaMA 2 70B" },
  { x: 13,  y: 70.6, label: "Mixtral 8x7B" },
  { x: 8,   y: 65.0, label: "LLaMA 3 8B" },
];

for (const pt of scatterPts) {
  const xPct = (pt.x - xMin) / (xMax - xMin);
